function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];

  function dfs(row, col, steps) {
    if (steps === k) {
      path.push(...grid[row][col]);
      return;
    }

    for (const [dx, dy] of directions) {
      const newRow = row + dx;
      const newCol = col + dy;

      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
        visited[newRow][newCol] = true;
        dfs(newRow, newCol, steps + 1);
        visited[newRow][newCol] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  path.sort((a, b) => a - b);

  return path;
}

