function last(arr, x) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    let mid = Math.floor((left + right) / 2);

    if (arr[mid] === x) {
      // If the element is found, move the right pointer to the left
      left = mid - 1;
    } else if (arr[mid] < x) {
      // If the element is greater, move the left pointer to the right
      left = mid + 1;
    } else {
      // If the element is less, move the right pointer to the left
      right = mid - 1;
    }
  }

  // If the element is not found, return -1
  return left;
}

