function fibfib(n) {
  if (n === 0 || n === 1) return 0;
  if (n === 2) return 1;

  let a = 0, b = 0, c = 1, d = 0;
  for (let i = 3; i <= n; i++) {
    d = a + b + c;
    a = b;
    b = c;
    c = d;
  }
  return d;
}

function is_multiply_prime(a) {
    if (a < 2) return false;

    let count = 0;
    for (let i = 2; i <= Math.sqrt(a); i++) {
        if (a % i === 0) {
            count++;
            if (count > 3) return false;
        }
    }

    return count === 3;
}

