function find_adverb_position(text){
  const adverbs = ["quickly", "slowly", "well", "badly", "goodly"];
  let adverbPosition = null;

  for (let i = 0; i < text.length; i++) {
    for (let j = i + 1; j < text.length; j++) {
      const substring = text.substring(i, j + 1);
      if (adverbs.includes(substring)) {
        adverbPosition = { index: i, length: substring.length };
        break;
      }
    }
    if (adverbPosition) break;
  }

  return adverbPosition;
}
